    # Helper function to check if a substring can repeat in a string
    def can_repeat(substring: str) -> bool:
        n = len(substring)
        if n * 2 > len(s):
            return False
        for i in range(n):
            if substring[i:i+n] in s:
                return True
        return False

    # Try to repeat the first character of the string
    if s[0] == s[s.find(s[0]):]:
        return can_repeat(s[0:s.find(s[0])])
    return False

    # Try to repeat the last character of the string
    if s[-1] == s[s.find(s[-1]):]:
        return can_repeat(s[-1:s.find(s[-1])])

    # Try to repeat the character at the middle
    for i in range(n//2):
        if s[i] == s[i+n//2]:
            return can_repeat(s[i:i+n//2])

    # If none of the above works, the string cannot be constructed
    return False
