def num_unique_bst(n):
    def backtrack(node):
        if not node:
            return [1, 1]

        left = backtrack(node.left)
        right = backtrack(node.right)

        for i in range(len(left)):
            for j in range(len(right)):
                if node.val < left[i] or node.val > right[j]:
                    continue
                # Unique BSTs cannot include duplicates
                if i == j:
                    continue
                # Update the count
                if left[i] + right[j] == n:
                    return [left[i] + right[j] + 1, left[i] + right[j] * left[i] * right[j]]

        return [0, 0]

    return backtrack(None)[1]
